    "answer": "Pelindung Wajah Khusus Bahaya Arc Flash Listrik (Arc Flash Face Shield) adalah peralatan keselamatan dalam kategori APD Kepala, Mata, Telinga & Pernapasan yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
