    "answer": "Respirator Setengah Wajah Elastomerik (Half Facepiece Respirator) adalah peralatan keselamatan dalam kategori APD Kepala, Mata, Telinga & Pernapasan yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
