    "section": "alat",
    "slug": "sepatu-keselamatan-bahaya-sengatan-listrik-eh-electrical-hazard-rated-boots",
    "title": "Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots)",
    "metaTitle": "Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots): Spesifikasi, Inspeksi & Standar K3",
    "description": "Panduan teknis Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots): standar kelayakan, spesifikasi SNI/EN/ANSI, prosedur inspeksi visual berkala, dan cara penggunaan aman di tempat kerja.",
    "answer": "Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots) adalah peralatan keselamatan dalam kategori APD Tubuh, Tangan, Kaki & Proteksi Jatuh yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
    "highlights": [
      "Kategori APD Tubuh, Tangan, Kaki & Proteksi Jatuh",
      "Standar Spesifikasi SNI / EN / ANSI",
      "Checklist Inspeksi & Uji Kelayakan",
      "Panduan Pemeliharaan Terstandar"
    ],
    "blocks": [
      {
        "heading": "Fungsi & Peranan Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots)",
        "paragraphs": [
          "Dalam operasional industri dan kepatuhan K3, Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots) memegang peranan krusial dalam melindungi personel serta aset dari potensi bahaya lingkungan kerja.",
          "Peralatan ini wajib memenuhi standar sertifikasi yang diakui secara nasional maupun internasional guna menjamin keandalan fungsi proteksinya saat digunakan."
        ]
      },
      {
        "heading": "Kriteria Kelayakan & Standar Teknis",
        "paragraphs": [
          "Sebelum digunakan, peralatan ini wajib diperiksa berdasarkan parameter teknis berikut:"
        ],
        "bullets": [
          "Kelengkapan sertifikat uji mutu dan label sertifikasi standar (SNI/EN/ANSI)",
          "Kondisi fisik bebas dari retak, deformasi, korosi, atau keausan berlebih",
          "Fungsi mekanisme penguncian, pegas, atau sensor bekerja dengan akurat",
          "Kesesuaian kapasitas beban kerja aman (Working Load Limit - WLL) dengan tugas"
        ]
      },
      {
        "heading": "Prosedur Inspeksi & Pemeliharaan Rutin",
        "paragraphs": [
          "Lakukan inspeksi visual pra-pemakaian oleh pengguna serta inspeksi formal berkala oleh tenaga kompeten yang tercatat dalam logbook peralatan keselamatan."
        ]
      },
      {
        "heading": "Kaitan dengan Regulasi & Pelatihan",
        "paragraphs": [
          "Penggunaan dan tata cara pemeriksaan peralatan ini diajarkan secara mendalam dalam program pembinaan teknis K3 Kemnaker RI dan sertifikasi kompetensi profesi BNSP terkait."
        ]
      }
    ],
    "faqs": [
      {
        "question": "Kapan Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots) harus ditarik dari penggunaan (diberhentikan)?",
        "answer": "Peralatan harus segera ditarik dari penggunaan apabila mengalami benturan keras/jatuh, menunjukkan cacat struktural, gagal uji inspeksi, atau telah melewati masa kedaluwarsa pakai pabrikan."
      },
      {
        "question": "Apakah Sepatu Keselamatan Bahaya Sengatan Listrik EH (Electrical Hazard Rated Boots) wajib memiliki sertifikasi standar?",
        "answer": "Ya, seluruh peralatan K3 wajib memiliki tanda sertifikasi standar resmi (seperti SNI, EN, ANSI, atau CE) untuk menjamin perlindungan keselamatan."
      }
    ],
