    "answer": "Manset Pelindung Lengan Kulit Pengelasan (Leather Welding Sleeves) adalah peralatan keselamatan dalam kategori APD Tubuh, Tangan, Kaki & Proteksi Jatuh yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
