    "answer": "Pompa Pengambil Sampel Gas Tabung Kolorimetri (Colorimetric Gas Sampling Pump) adalah peralatan keselamatan dalam kategori Alat Deteksi Gas, Higiene & Pengukuran K3 yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
