    "slug": "instrumen-penguji-tahanan-pembumian-tanah-earth-ground-resistance-tester",
    "title": "Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester)",
    "metaTitle": "Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester): Spesifikasi, Inspeksi & Standar K3",
    "description": "Panduan teknis Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester): standar kelayakan, spesifikasi SNI/EN/ANSI, prosedur inspeksi visual berkala, dan cara penggunaan aman di tempat kerja.",
    "answer": "Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester) adalah peralatan keselamatan dalam kategori Alat Deteksi Gas, Higiene & Pengukuran K3 yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
    "highlights": [
      "Kategori Alat Deteksi Gas, Higiene & Pengukuran K3",
      "Standar Spesifikasi SNI / EN / ANSI",
      "Checklist Inspeksi & Uji Kelayakan",
      "Panduan Pemeliharaan Terstandar"
    ],
    "blocks": [
      {
        "heading": "Fungsi & Peranan Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester)",
        "paragraphs": [
          "Dalam operasional industri dan kepatuhan K3, Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester) memegang peranan krusial dalam melindungi personel serta aset dari potensi bahaya lingkungan kerja.",
          "Peralatan ini wajib memenuhi standar sertifikasi yang diakui secara nasional maupun internasional guna menjamin keandalan fungsi proteksinya saat digunakan."
        ]
      },
      {
        "heading": "Kriteria Kelayakan & Standar Teknis",
        "paragraphs": [
          "Sebelum digunakan, peralatan ini wajib diperiksa berdasarkan parameter teknis berikut:"
        ],
        "bullets": [
          "Kelengkapan sertifikat uji mutu dan label sertifikasi standar (SNI/EN/ANSI)",
          "Kondisi fisik bebas dari retak, deformasi, korosi, atau keausan berlebih",
          "Fungsi mekanisme penguncian, pegas, atau sensor bekerja dengan akurat",
          "Kesesuaian kapasitas beban kerja aman (Working Load Limit - WLL) dengan tugas"
        ]
      },
      {
        "heading": "Prosedur Inspeksi & Pemeliharaan Rutin",
        "paragraphs": [
          "Lakukan inspeksi visual pra-pemakaian oleh pengguna serta inspeksi formal berkala oleh tenaga kompeten yang tercatat dalam logbook peralatan keselamatan."
        ]
      },
      {
        "heading": "Kaitan dengan Regulasi & Pelatihan",
        "paragraphs": [
          "Penggunaan dan tata cara pemeriksaan peralatan ini diajarkan secara mendalam dalam program pembinaan teknis K3 Kemnaker RI dan sertifikasi kompetensi profesi BNSP terkait."
        ]
      }
    ],
    "faqs": [
      {
        "question": "Kapan Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester) harus ditarik dari penggunaan (diberhentikan)?",
        "answer": "Peralatan harus segera ditarik dari penggunaan apabila mengalami benturan keras/jatuh, menunjukkan cacat struktural, gagal uji inspeksi, atau telah melewati masa kedaluwarsa pakai pabrikan."
      },
      {
        "question": "Apakah Instrumen Penguji Tahanan Pembumian Tanah (Earth Ground Resistance Tester) wajib memiliki sertifikasi standar?",
        "answer": "Ya, seluruh peralatan K3 wajib memiliki tanda sertifikasi standar resmi (seperti SNI, EN, ANSI, atau CE) untuk menjamin perlindungan keselamatan."
      }
    ],
