    "answer": "Kit Kalibrasi Gas Standar (Span Calibration Gas Cylinder & Regulator) adalah peralatan keselamatan dalam kategori Alat Deteksi Gas, Higiene & Pengukuran K3 yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
