    "answer": "Tali Bulat Pembungkus Beban Tanpa Sambungan (Round Sling Endless 5 Ton) adalah peralatan keselamatan dalam kategori Peralatan Rigging, Scaffolding, LOTO & Penunjang yang dirancang untuk melindungi pekerja, mendeteksi bahaya, serta memitigasi risiko insiden di tempat kerja.",
